"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[7268],{37121(e){e.exports=JSON.parse('{"ko_kr":{"AnimaAnimus":{"achievement_value":"\ub2ec\uc131\uce58","critical":"\ud06c\ub9ac\ud2f0\uceec \ubc1c\uc0dd","table":{"IGT":{"name":"\uc815\ubcf4 \uc218\uc9d1\ud45c","type":"1d10","items":["\uc2a4\ud2b8\ub9ac\ud2b8 \ud30c\uc774\ud2b8/<\uaca9\ud22c>/\u300c\ub098\ud55c\ud14c \uc774\uae30\uba74 \uc54c\ub824\uc8fc\uc9c0\u300d\uc815\ubcf4\ub97c \uc544\ub294 \ud63c\uc6d0\uc790\uc5d0\uac8c \uc2b9\ubd80\ub97c \ub3c4\uc804\ubc1b\uc558\ub2e4. \uc0b4\uc544\ub0a8\uae30 \uc704\ud574\uc11c\ub77c\ub3c4 \uc774 \uc2f8\uc6c0, \uc9c8 \uc218\ub294 \uc5c6\ub2e4.","\ucd94\uc801!/<\ucd94\uc801/\ub3c4\uc8fc>/\uc720\uc775\ud55c \uc815\ubcf4\ub97c \uac00\uc9c4 \uc778\ubb3c\uc744 \ubc1c\uacac\ud588\uc9c0\ub9cc, \uc774\ucabd \uc5bc\uad74\uc744 \ubcf4\uc790\ub9c8\uc790 \ub3c4\ub9dd\uccd0 \ubc84\ub838\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uc7a1\uc544\uc57c\ub9cc \ud55c\ub2e4.","\ud611\ubc15/<\uc704\uc555>/\ubd88\ub7c9\ubc30\ub4e4\uc774 \ubaa8\uc774\ub294 \ubc14\uc5d0 \ucc3e\uc544\uc654\ub2e4. \ub4b7\uc138\uacc4\uc5d0 \uc0ac\ub294 \uadf8\ub4e4\uc744 \ud611\ubc15\ud558\uba74 \uc720\uc775\ud55c \uc815\ubcf4\ub97c \uc5bb\uc744 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.","\uc778\ud130\ub137/<\ucef4\ud4e8\ud130>/SNS\ub098 \ub274\uc2a4 \ub4f1, \uc778\ud130\ub137\uc0c1\uc758 \uc815\ubcf4\ub97c \uc870\uc0ac\ud55c\ub2e4. \uac00\uc9dc \ub274\uc2a4\uc5d0 \uc18d\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4.","\ube48\uc0ac\uc758 \uc815\ubcf4 \uc81c\uacf5\uc790/<\uc758\ud559>/\uc815\ubcf4\ub97c \uc544\ub294 \uc778\ubb3c\uc774 \uc788\ub2e4\ub294 \ub9d0\uc744 \ub4e3\uace0 \ucc3e\uc544\uac14\ub354\ub2c8, \uadf8 \uc778\ubb3c\uc774 \ube48\uc0ac \uc0c1\ud0dc\uc758 \uc911\uc0c1\uc744 \uc785\uace0 \uc788\uc5c8\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uc18c\uc0dd\uc2dc\ucf1c\uc57c \ud55c\ub2e4.","\uc7a0\uc785 \uc218\uc0ac/<\uc740\ubc00>/\uc801\ub300\ud558\ub294 \ud63c\uc6d0\uc790 \uadf8\ub8f9\uc5d0 \uc7a0\uc785\ud574 \uc870\uc0ac \ud65c\ub3d9\uc744 \ud3bc\uce5c\ub2e4. \uc704\ud5d8\uc740 \ub192\uc9c0\ub9cc \uc720\uc775\ud55c \uc815\ubcf4\ub97c \uc5bb\uc744 \ud655\ub960\ub3c4 \ub192\ub2e4.","\uc815\ubcf4 \uad50\ud658/<\uad50\uc12d>/\uc6b0\ud638\uc801\uc778 \uad00\uacc4\uc5d0 \uc788\ub294 \ud63c\uc6d0\uc790\uc640 \uc815\ubcf4\ub97c \uad50\ud658\ud55c\ub2e4. \uc798 \uc774\uc57c\uae30\ub97c \ub4e4\uc5b4\ub0bc \uc218 \uc788\uc73c\uba74 \uc88b\uaca0\uc9c0\ub9cc.","\ub9c8\uc5f0\uc758 \uc815\ubcf4\uc0c1/<\uc870\ub2ec>/\ub9c8\uc5f0\uc758 \uc815\ubcf4\uc0c1\uc5d0 \uc811\ucd09\ud574 \uc815\ubcf4\ub97c \uce90\ub0b4\uae30\ub85c \ud588\ub2e4. \ub9cc\ub9cc\ucc2e\uc740 \uc0c1\ub300\uc778 \uac83 \uac19\uc740\ub370, \uacfc\uc5f0\u2026\u2026?","\ubd88\ubc95 \uc870\uc0ac/<\ubc94\uc8c4>/\ubc95\uc5d0 \uc800\ucd09\ub418\ub294 \ubc29\ubc95\uc73c\ub85c \uc815\ubcf4\ub97c \ubaa8\uc73c\uae30\ub85c \ud588\ub2e4. \ud574\ud0b9, \uc808\ub3c4, \uacf5\uac08, \uc5b4\ub5a4 \uc218\ub2e8\uc744 \uc120\ud0dd\ud560\uae4c.","\ud0d0\ubb38/<\uc790\uc544>/\uac70\ub9ac\ub97c \uc624\uac00\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud0d0\ubb38 \uc218\uc0ac\ub97c \uc2e4\uc2dc\ud55c\ub2e4. \uafb8\uc900\ud55c \ud65c\ub3d9\uc774\uc57c\ub9d0\ub85c \ubaa9\ud45c\uc5d0 \ub3c4\ub2ec\ud558\uae30 \uc704\ud55c \uac00\uc7a5 \ube60\ub978 \ubc29\ubc95\uc774\ub2e4."]},"LT":{"name":"\uc0c1\uc2e4\ud45c","type":"1d10","items":[["1..2","\uc874\uc7ac/\uc874\uc7ac\uac00 \ud76c\ubbf8\ud574\uc838, \uc9c0\uc778\uc774\ub098 \uce5c\uad6c\uc5d0\uac8c \uc790\uc2e0\uc758 \uc874\uc7ac\ub97c \uc78a\ud600\ubc84\ub9b0\ub2e4. \uba38\uc9c0\uc54a\uc544 \uc18c\uc911\ud55c \ud30c\ud2b8\ub108\uc758 \uae30\uc5b5\uc5d0\uc11c\ub3c4 \uc0ac\ub77c\uc838, \uc774 \uc138\uacc4\uc5d0\uc11c \ud63c\uc790\uac00 \ub41c\ub2e4.\\n\uc790\uc2e0\uc758 \ucd9c\uc2e0\uc744 \uc0ad\uc81c\ud560 \uac83."],["3..4","\uae30\uc5b5/\uc18c\uc911\ud55c \uae30\uc5b5\uc744 \ud558\ub098 \uc783\ub294\ub2e4. \uc55e\uc73c\ub85c\ub294 \ud798\uc744 \uc0ac\uc6a9\ud560 \ub54c\ub9c8\ub2e4 \uae30\uc5b5\uc744 \ud558\ub098\uc529 \uc783\uac8c \ub418\uba70, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc18c\uc911\ud55c \ud30c\ud2b8\ub108\uc758 \uc77c\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc5c6\uac8c \ub41c\ub2e4.\\n\uc790\uc2e0\uc758 \uba54\ubaa8\ub9ac\uc544\ub97c \ud558\ub098 \uc120\ud0dd\ud558\uc5ec \uc0ad\uc81c\ud560 \uac83. \uc2dc\ub098\ub9ac\uc624 \uba54\ubaa8\ub9ac\uc544\ub294 \uc120\ud0dd\ud560 \uc218 \uc5c6\ub2e4."],["5..6","\uc6a9\ubaa8/\uc810\uc810 \uc608\uc804\uacfc\ub294 \ub3d9\ub5a8\uc5b4\uc9c4 \ubaa8\uc2b5\uc73c\ub85c \ubcc0\ud574\uac04\ub2e4. \uc5b8\uc820\uac00 \uc544\ubb34\ub3c4 \uc790\uc2e0\uc744 \uc790\uc2e0\uc774\ub77c\uace0 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud558\uac8c \ub418\ub294 \uac83\uc77c\uae4c.\\n\uc790\uc2e0\uc758 \ud2b9\uc9d5\uc801\uc778 \uc678\ubaa8\ub97c \uc783\ub294\ub2e4. \ub0b4\uc6a9\uc744 \uc801\uc808\ud55c \uac83\uc73c\ub85c \ubc14\uafd4 \uc4f8 \uac83(\ud2b9\uc9d5\uc801\uc778 \uc678\ubaa8\uac00 \uc544\ub984\ub2e4\uc6b4 \uba38\ub9ac\uce74\ub77d\uc774\ub77c\uba74 \ud749\ud55c \uba38\ub9ac\uce74\ub77d \ub4f1)."],["7..8","\uac10\uc815/\ud76c\ub178\uc560\ub77d\uc758 \uac10\uc815 \uc911 \uc5b4\ub290 \ud558\ub098\ub97c \uc783\ub294\ub2e4. \ud798\uc744 \uc0ac\uc6a9\ud560 \ub54c\ub9c8\ub2e4 \ub2e4\ub978 \uac10\uc815\ub3c4 \uc783\uc5b4\uac00\uba70, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uadf8\uc800 \uc0b4\uc544\ub0a8\uae30 \uc704\ud574 \uc2f8\uc6b0\ub294 \uae30\uacc4\uac00 \ub41c\ub2e4.\\n\ud3ec\uc9c0\ud2f0\ube0c\uc640 \ub124\uac70\ud2f0\ube0c \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud55c\ub2e4. \uc120\ud0dd\ud55c \uac10\uc815\uc744 \ubaa8\ub4e0 \uba54\ubaa8\ub9ac\uc544\uc5d0\uc11c \uc0ad\uc81c\ud55c\ub2e4. \uc0ad\uc81c\ud55c \uacb0\uacfc, \ubc1c\ud604 \uac10\uc815\uc774 \uc5c6\uc5b4\uc9c4 \uacbd\uc6b0, \ub0a8\uc740 \uac10\uc815\uc744 \ubc1c\ud604 \uac10\uc815\uc73c\ub85c \ud560 \uac83. \ub610\ud55c, \uc0c8\ub85c\uc6b4 \uba54\ubaa8\ub9ac\uc544\ub97c \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc120\ud0dd\ud55c \uac10\uc815\uc744 \uc5bb\uc744 \uc218 \uc5c6\ub2e4."],["9..10","\uc624\uac10/\uc870\uae08\uc529 \uc624\uac10\uc774 \ub454\ud574\uc9c4\ub2e4. \uc9c0\uae08\uae4c\uc9c0 \ud560 \uc218 \uc788\uc5c8\ub358 \uc77c\uc744 \ud560 \uc218 \uc5c6\uac8c \ub418\uc5b4\ubc84\ub9b0\ub2e4.\\n\uc790\uc2e0\uc758 \ud2b9\uae30\ub97c \ud558\ub098 \uc120\ud0dd\ud55c\ub2e4. \uc120\ud0dd\ud55c \ud2b9\uae30\uc5d0 \xd7\ub97c \uccb4\ud06c\ud560 \uac83. \xd7\uac00 \uccb4\ud06c\ub41c \uae30\ub2a5\uc73c\ub85c\ub294 \ud310\uc815\uc744 \ud560 \uc218 \uc5c6\uc73c\uba70, \ud310\uc815 \uc2dc \uc790\ub3d9\uc73c\ub85c \uc2e4\ud328\ud55c\ub2e4."]]}}}}}')}}]);